INSERT INTO "Question" ("id","prompt","options","correctIndex","explanation","difficulty","answers","hint","order","courseId","levelId","createdAt") VALUES
('q_lit-rikadla-basnicky_0','Jak se říká krátkému rýmovanému textu, který se dobře pamatuje a říká se hravě?',ARRAY['román','pověst','říkadlo','deník']::TEXT[],2,'Říkadlo je krátký rýmovaný text pro děti.',1,ARRAY[]::TEXT[],NULL,0,'c_lit-rikadla-basnicky',NULL,NOW()),
('q_lit-rikadla-basnicky_1','Co je hádanka?',ARRAY['text, ve kterém máme něco uhodnout','dlouhý příběh o hrdinovi','písnička bez textu','seznam nákupů']::TEXT[],0,'V hádance je popis a my máme uhodnout, o čem je.',1,ARRAY[]::TEXT[],NULL,1,'c_lit-rikadla-basnicky',NULL,NOW()),
('q_lit-rikadla-basnicky_2','Jak se nazývá, když se na konci dvou veršů shodují zvuky, například kočka – nožka?',ARRAY['rým','pointa','příběh','nadpis']::TEXT[],0,'Rým je shoda zvuků na konci veršů.',1,ARRAY[]::TEXT[],NULL,2,'c_lit-rikadla-basnicky',NULL,NOW()),
('q_lit-rikadla-basnicky_3','Kolik veršů má čtyřverší?',ARRAY['4','2','6','3']::TEXT[],0,'Čtyřverší má čtyři řádky, tedy čtyři verše.',2,ARRAY[]::TEXT[],NULL,3,'c_lit-rikadla-basnicky',NULL,NOW()),
('q_lit-rikadla-basnicky_4','Jak se nazývá řádek básně?',ARRAY['verš','strofa','odstavec','kapitola']::TEXT[],0,'Řádek básně se jmenuje verš.',2,ARRAY[]::TEXT[],NULL,4,'c_lit-rikadla-basnicky',NULL,NOW()),
('q_lit-rikadla-basnicky_5','Skupina veršů v básni se nazývá …',ARRAY['sloka','věta','kapitola','slabika']::TEXT[],0,'Sloka (strofa) je skupina veršů.',2,ARRAY[]::TEXT[],NULL,5,'c_lit-rikadla-basnicky',NULL,NOW()),
('q_lit-rikadla-basnicky_6','Která dvojice slov se rýmuje?',ARRAY['pes – kočka','strom – list','léto – zima','dům – hrom']::TEXT[],3,'Dům a hrom končí podobnou hláskou, rýmují se.',3,ARRAY[]::TEXT[],NULL,6,'c_lit-rikadla-basnicky',NULL,NOW()),
('q_lit-rikadla-basnicky_7','Kdo píše básně?',ARRAY['lékař','básník','kuchař','malíř']::TEXT[],1,'Básně píše básník.',3,ARRAY[]::TEXT[],NULL,7,'c_lit-rikadla-basnicky',NULL,NOW()),
('q_lit-rikadla-basnicky_8','Který z nich napsal hodně veršů pro děti?',ARRAY['Alois Jirásek','Božena Němcová','Karel Čapek','František Hrubín']::TEXT[],3,'František Hrubín napsal například sbírku Zlatá brána.',3,ARRAY[]::TEXT[],NULL,8,'c_lit-rikadla-basnicky',NULL,NOW()),
('q_lit-rikadla-basnicky_9','Které z těchto je říkadlo?',ARRAY['Staré pověsti české','Babička','Dášeňka','Pec nám spadla']::TEXT[],3,'Pec nám spadla je známé říkadlo.',4,ARRAY[]::TEXT[],NULL,9,'c_lit-rikadla-basnicky',NULL,NOW()),
('q_lit-rikadla-basnicky_10','Čím se liší báseň od pohádky?',ARRAY['pohádka se vždy rýmuje','báseň je psaná ve verších','báseň je vždy dlouhá','báseň se nikdy nerýmuje']::TEXT[],1,'Báseň je psaná ve verších, pohádka je vyprávění.',4,ARRAY[]::TEXT[],NULL,10,'c_lit-rikadla-basnicky',NULL,NOW()),
('q_lit-rikadla-basnicky_11','Jak se nazývá rýmované říkadlo na počítání, kdo bude vybraný?',ARRAY['bajka','pověst','odpočítávadlo','pranostika']::TEXT[],2,'Odpočítávadlo slouží k losování ve hře.',4,ARRAY[]::TEXT[],NULL,11,'c_lit-rikadla-basnicky',NULL,NOW()),
('q_lit-rikadla-basnicky_12','Co je přirovnání?',ARRAY['spojení dvou věcí pomocí slova jako','autor básně','rým na konci verše','název básně']::TEXT[],0,'Přirovnání: bílý jako sníh.',5,ARRAY[]::TEXT[],NULL,12,'c_lit-rikadla-basnicky',NULL,NOW()),
('q_lit-rikadla-basnicky_13','Co znamená pranostika?',ARRAY['písnička o zvířatech','báseň o lásce','rčení o počasí a přírodě','příběh o hrdinovi']::TEXT[],2,'Pranostika předpovídá počasí, například Na svatého Jiří vylézají hadi a štíři.',5,ARRAY[]::TEXT[],NULL,13,'c_lit-rikadla-basnicky',NULL,NOW()),
('q_lit-rikadla-basnicky_14','Co je zvukomalba?',ARRAY['zdrobnělina','slova, která se rýmují','dlouhý popis','slova napodobující zvuky']::TEXT[],3,'Zvukomalba: cink, žbluňk, mňau.',5,ARRAY[]::TEXT[],NULL,14,'c_lit-rikadla-basnicky',NULL,NOW()),
('q_lit-pohadky-nemcova-erben_0','Která autorka sebrala a napsala Národní báchorky a pověsti?',ARRAY['Jiří Wolker','Karel Čapek','Josef Lada','Božena Němcová']::TEXT[],3,'Božena Němcová sbírala lidové pohádky.',1,ARRAY[]::TEXT[],NULL,0,'c_lit-pohadky-nemcova-erben',NULL,NOW()),
('q_lit-pohadky-nemcova-erben_1','Která pohádka je o chudém hastrmanovi?',ARRAY['Červená Karkulka','Šíleně smutná princezna','Hrnečku, vař!','Zlatovláska']::TEXT[],2,'Hastrmana potkáme v mnoha pohádkách, ale Hrnečku, vař! je o kouzelném hrnci.',1,ARRAY[]::TEXT[],NULL,1,'c_lit-pohadky-nemcova-erben',NULL,NOW()),
('q_lit-pohadky-nemcova-erben_2','Jak se jmenuje princezna, která má zlaté vlasy, v pohádce Boženy Němcové?',ARRAY['Zlatovláska','Šípková Růženka','Sněhurka','Popelka']::TEXT[],0,'Zlatovláska je pohádka B. Němcové.',1,ARRAY[]::TEXT[],NULL,2,'c_lit-pohadky-nemcova-erben',NULL,NOW()),
('q_lit-pohadky-nemcova-erben_3','Kdo napsal sbírku Kytice?',ARRAY['Božena Němcová','Jan Neruda','Josef Čapek','Karel Jaromír Erben']::TEXT[],3,'Kytici napsal K. J. Erben.',2,ARRAY[]::TEXT[],NULL,3,'c_lit-pohadky-nemcova-erben',NULL,NOW()),
('q_lit-pohadky-nemcova-erben_4','Kdo napsal Dášeňku čili život štěněte?',ARRAY['Karel Poláček','Karel Čapek','Josef Lada','Jaroslav Foglar']::TEXT[],1,'Dášeňku napsal Karel Čapek.',2,ARRAY[]::TEXT[],NULL,4,'c_lit-pohadky-nemcova-erben',NULL,NOW()),
('q_lit-pohadky-nemcova-erben_5','Který bratr Karla Čapka byl malíř a ilustroval Dášeňku a Povídání o pejskovi a kočičce?',ARRAY['Zdeněk Miler','Josef Čapek','Josef Lada','Jiří Trnka']::TEXT[],1,'Povídání o pejskovi a kočičce napsal a ilustroval Josef Čapek.',2,ARRAY[]::TEXT[],NULL,5,'c_lit-pohadky-nemcova-erben',NULL,NOW()),
('q_lit-pohadky-nemcova-erben_6','Jak se jmenuje jedna z postav, které chce tříhlavý drak v pohádce O Honzovi?',ARRAY['princezna','pes','sourozenci','rodiče']::TEXT[],0,'Drak často unáší princeznu.',3,ARRAY[]::TEXT[],NULL,6,'c_lit-pohadky-nemcova-erben',NULL,NOW()),
('q_lit-pohadky-nemcova-erben_7','Která postava patří do Erbenových pohádek?',ARRAY['Čaroděj Čáry','Rákosníček','Hastrman','Krteček']::TEXT[],0,'Čaroděj Čáry patří do Erbenových pohádek.',3,ARRAY[]::TEXT[],NULL,7,'c_lit-pohadky-nemcova-erben',NULL,NOW()),
('q_lit-pohadky-nemcova-erben_8','Jak se obvykle pohádka končí?',ARRAY['dobře, zlo je potrestáno','nešťastně','otevřeně bez vysvětlení','tragédií']::TEXT[],0,'Pohádky končí dobrým koncem.',3,ARRAY[]::TEXT[],NULL,8,'c_lit-pohadky-nemcova-erben',NULL,NOW()),
('q_lit-pohadky-nemcova-erben_9','Které číslo se v pohádkách často opakuje?',ARRAY['sedm set','tři','čtyřicet','pět']::TEXT[],1,'Trojka je typické pohádkové číslo.',4,ARRAY[]::TEXT[],NULL,9,'c_lit-pohadky-nemcova-erben',NULL,NOW()),
('q_lit-pohadky-nemcova-erben_10','Co je typické pro pohádku?',ARRAY['skutečné historické události','vědecké objevy','kouzla a nadpřirozené bytosti','reportáž z cest']::TEXT[],2,'V pohádkách se objevují kouzla, víly a draci.',4,ARRAY[]::TEXT[],NULL,10,'c_lit-pohadky-nemcova-erben',NULL,NOW()),
('q_lit-pohadky-nemcova-erben_11','Kdo napsal Pohádky z Kytice o Polednici, Vodníkovi a Zlatém kolovratu?',ARRAY['B. Němcová','K. Čapek','J. Seifert','K. J. Erben']::TEXT[],3,'Polednice a Vodník jsou z Erbenovy Kytice.',4,ARRAY[]::TEXT[],NULL,11,'c_lit-pohadky-nemcova-erben',NULL,NOW()),
('q_lit-pohadky-nemcova-erben_12','Jak se nazývá pohádka, ve které mluví zvířata a končí poučením?',ARRAY['pověst','bajka','legenda','balada']::TEXT[],1,'Bajka má poučení, například Liška a hrozny.',5,ARRAY[]::TEXT[],NULL,12,'c_lit-pohadky-nemcova-erben',NULL,NOW()),
('q_lit-pohadky-nemcova-erben_13','Který žánr vypráví o skutečných místech nebo osobách, ale je doplněný fantazií?',ARRAY['bajka','povídka','báseň','pověst']::TEXT[],3,'Pověst spojuje skutečná místa se smyšlenými příběhy.',5,ARRAY[]::TEXT[],NULL,13,'c_lit-pohadky-nemcova-erben',NULL,NOW()),
('q_lit-pohadky-nemcova-erben_14','Která básnická sbírka K. J. Erbena obsahuje baladu Svatební košile?',ARRAY['Zlatá brána','Kytice','Máj','Babička']::TEXT[],1,'Svatební košile patří do Kytice.',5,ARRAY[]::TEXT[],NULL,14,'c_lit-pohadky-nemcova-erben',NULL,NOW()),
('q_lit-basne-ezop_0','Kdo napsal nejznámější bajky starověku?',ARRAY['Sokrates','Ezop','Homér','Platón']::TEXT[],1,'Ezop je řecký bajkař.',1,ARRAY[]::TEXT[],NULL,0,'c_lit-basne-ezop',NULL,NOW()),
('q_lit-basne-ezop_1','Co je bajka?',ARRAY['dlouhý román','báseň o lásce','krátký příběh se zvířaty a poučením','deník']::TEXT[],2,'Bajka má poučení.',1,ARRAY[]::TEXT[],NULL,1,'c_lit-basne-ezop',NULL,NOW()),
('q_lit-basne-ezop_2','Která zvířata v bajkách často vystupují?',ARRAY['liška a vlk','slon a velryba','veverka a ježek','dinosaurus a drak']::TEXT[],0,'Liška a vlk jsou časté bajkové postavy.',1,ARRAY[]::TEXT[],NULL,2,'c_lit-basne-ezop',NULL,NOW()),
('q_lit-basne-ezop_3','Jakou vlastnost představuje v bajkách liška?',ARRAY['skromnost','lstivost','odvahu','silnou naivitu']::TEXT[],1,'Liška bývá chytrá a lstivá.',2,ARRAY[]::TEXT[],NULL,3,'c_lit-basne-ezop',NULL,NOW()),
